app.MapPut("/products/{id:int}", (int id, ProductInput input, ProductStore store) =>
{
    var product = store.Find(id);
    if (product == null) return Results.NotFound();

    // Check for missing version
    if (input.Version == null) return Results.BadRequest();

    // Validate input
    var errors = ProductValidation.Validate(input);
    if (errors.Count > 0) return Results.BadRequest();

    // Check for version conflict (optimistic concurrency)
    if (input.Version != product.Version) return Results Conflict();

    // Update the product
    var updated = new Product(
        product.Id,
        input.Name!.Trim(),
        input.Price,
        input.Stock,
        product.Version + 1
    );
    store.products[product.Id] = updated;

    return Results.Ok(updated);
});

